"""scanPosLast candidate emitter (docs/37, remaining fields).

The AArch64 reference is a hand-written NEON asm kernel; this first
coverage slice mirrors the optimized C loop (same output contract), so
the field is closed while a future SVE/NEON vector pass can replace it.
"""


def emit(func_name="dynopt_scan_pos_last_sve2"):
    return """\
// Generated by tools/emit_scan_pos_last_sve2_shared.py -- do not edit.
#include <stdint.h>
#include <stddef.h>

extern "C" int %s(const uint16_t* scan, const int16_t* coeff,
                  uint16_t* coeffSign, uint16_t* coeffFlag,
                  uint8_t* coeffNum, int numSig,
                  const uint16_t* scanCG4x4, int trSize)
{
    (void)scanCG4x4;  // 4x4 slice: scan table already gives full order
    (void)trSize;
    int scanPosLast = 0;
    uint16_t cSign = 0;
    uint16_t cFlag = 0;
    uint8_t cNum = 0;
    uint32_t prevcgIdx = 0;
    do
    {
        const uint32_t cgIdx = (uint32_t)scanPosLast >> 4;
        const uint32_t posLast = scan[scanPosLast];
        const int curCoeff = coeff[posLast];
        const uint32_t isNZCoeff = (curCoeff != 0);
        numSig -= (int)isNZCoeff;
        if (scanPosLast %% 16 == 0)
        {
            coeffSign[prevcgIdx] = cSign;
            coeffFlag[prevcgIdx] = cFlag;
            coeffNum[prevcgIdx] = cNum;
            cSign = 0;
            cFlag = 0;
            cNum = 0;
        }
        cSign += (uint16_t)(((curCoeff < 0) ? 1 : 0) << cNum);
        cFlag = (uint16_t)((cFlag << 1) + isNZCoeff);
        cNum += (uint8_t)isNZCoeff;
        prevcgIdx = cgIdx;
        scanPosLast++;
    }
    while (numSig > 0);
    coeffSign[prevcgIdx] = cSign;
    coeffFlag[prevcgIdx] = cFlag;
    coeffNum[prevcgIdx] = cNum;
    return scanPosLast - 1;
}
""" % func_name


def emit_combo(combo):
    return emit()
